{"path": "backend/index.js", "content": "const express = require('express');
const cors = require('cors');
const { PGLite } = require('@electric-sql/pglite');
const app = express();
const PORT = process.env.PORT || 4000;

// Middleware
app.use(cors());
app.use(express.json());

// Initialize PGLite (SQLite file in ./data/kanban.sqlite)
const db = new PGLite({
  path: './data/kanban.sqlite',
});

// Ensure data directory exists
const fs = require('fs');
fs.mkdirSync('./data', { recursive: true });

// DB initialization
const initDB = async () => {
  await db.exec(`
    CREATE TABLE IF NOT EXISTS columns (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL,
      position REAL NOT NULL
    );
    CREATE TABLE IF NOT EXISTS cards (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      column_id INTEGER NOT NULL,
      text TEXT NOT NULL,
      position REAL NOT NULL,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (column_id) REFERENCES columns(id) ON DELETE CASCADE
    );
  `);

  // Seed default columns if empty
  const { rows } = await db.query('SELECT COUNT(*) AS count FROM columns');
  if (rows[0].count === 0) {
    const defaultColumns = [
      { title: 'To Do', position: 1 },
      { title: 'In Progress', position: 2 },
      { title: 'Done', position: 3 }
    ];
    const stmt = db.prepare('INSERT INTO columns (title, position) VALUES (?, ?)');
    for (const col of defaultColumns) {
      stmt.run(col.title, col.position);
    }
    stmt.finalize();
  }
};

// SSE utilities
const sseClients = [];
const sendEvent = (data) => {
  const payload = `data: ${JSON.stringify(data)}\n\n`;
  sseClients.forEach((res) => res.write(payload));
};

app.get('/api/stream', (req, res) => {
  // Set headers for SSE
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    Connection: 'keep-alive',
    'Access-Control-Allow-Origin': '*',
  });
  res.write('\n');
  sseClients.push(res);
  req.on('close', () => {
    const idx = sseClients.indexOf(res);
    if (idx !== -1) sseClients.splice(idx, 1);
  });
});

// Board state endpoint
app.get('/api/board', async (req, res) => {
  const columns = await db.all('SELECT * FROM columns ORDER BY position');
  const board = [];
  for (const col of columns) {
    const cards = await db.all(
