  const newPos = maxPos + 1;
  const result = await db.run('INSERT INTO cards (column_id, text, position) VALUES ($cid, $txt, $pos)', {
    $cid: columnId,
    $txt: text,
    $pos: newPos
  });
  const card = await db.get('SELECT * FROM cards WHERE id = $id', { $id: result.lastInsertRowid });
